export function evaluate({ inputs, time, seed, state }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = inputs.gravity;
  const apexTime = launchSpeed / gravity;
  const apexHeight = (launchSpeed * launchSpeed) / (2 * gravity);

  const t = time;
  const tossedVelocity = launchSpeed - gravity * t;
  const tossedHeight = launchSpeed * t - (gravity * t * t) / 2;
  const tossedAcceleration = -gravity;

  let dropVelocity = 0;
  let dropAcceleration = 0;
  let dropHeight = apexHeight;

  if (t >= apexTime) {
    const dt = t - apexTime;
    dropVelocity = -gravity * dt;
    dropAcceleration = -gravity;
    dropHeight = apexHeight - (gravity * dt * dt) / 2;
  }

  let tossState = "Rising";
  if (t <= 0.05) tossState = "At launch";
  else if (Math.abs(t - apexTime) < 0.05) tossState = "At the top";
  else if (t > apexTime) tossState = "Falling";
  if (tossedHeight <= 0 && t > apexTime) tossState = "At launch height";

  let dropState = "Held in place";
  if (Math.abs(t - apexTime) < 0.05) dropState = "Just released";
  else if (t > apexTime) dropState = "Falling together";
  if (dropHeight <= 0 && t > apexTime) dropState = "At launch height";

  const scaleY = 120;
  const baseY = 320;
  const tossX = 200;
  const dropX = 440;

  const ballTossY = baseY - tossedHeight * scaleY;
  const ballDropY = baseY - dropHeight * scaleY;
  const apexY = baseY - apexHeight * scaleY;

  const objects = [];

  objects.push(...sdk.panel({ x: 40, y: 60, w: 260, h: 330, title: "Toss lane", state: tossState, id: "lane.toss" }));
  objects.push(...sdk.panel({ x: 340, y: 60, w: 260, h: 330, title: "Drop lane", state: dropState, id: "lane.drop" }));

  objects.push(sdk.axis("axis.toss", { x: tossX - 60, y: baseY, length: 260, orientation: "y", min: 0, max: 2.2, label: "Height", unit: "m" }));
  objects.push(sdk.axis("axis.drop", { x: dropX - 60, y: baseY, length: 260, orientation: "y", min: 0, max: 2.2, label: "Height", unit: "m" }));

  objects.push(sdk.circle("ball.toss", tossX, ballTossY, 28, { role: "observed" }));
  objects.push(sdk.circle("ball.drop", dropX, ballDropY, 28, { role: "output" }));

  if (t < apexTime) {
    objects.push(...sdk.gate("gate", dropX, apexY, { open: false, label: "Gate" }));
  } else {
    objects.push(...sdk.gate("gate", dropX, apexY, { open: true, label: "Gate" }));
  }

  objects.push(...sdk.vector("vec.v.toss", { x: tossX - 25, y: ballTossY }, { value: tossedVelocity, direction: "up" }, { scale: 15, label: "v" }));
  objects.push(...sdk.vector("vec.a.toss", { x: tossX + 25, y: ballTossY }, { value: tossedAcceleration, direction: "up" }, { scale: 8, label: "a" }));

  objects.push(...sdk.vector("vec.v.drop", { x: dropX - 25, y: ballDropY }, { value: dropVelocity, direction: "up" }, { scale: 15, label: "v" }));
  objects.push(...sdk.vector("vec.a.drop", { x: dropX + 25, y: ballDropY }, { value: dropAcceleration, direction: "up" }, { scale: 8, label: "a" }));

  objects.push(...sdk.callout(tossX + 45, ballTossY - 20, [
    "v: " + sdk.format(tossedVelocity, 2) + " m/s",
    "a: " + sdk.format(tossedAcceleration, 1) + " m/s^2"
  ], { id: "callout.toss" }));

  objects.push(...sdk.callout(dropX + 45, ballDropY - 20, [
    "v: " + sdk.format(dropVelocity, 2) + " m/s",
    "a: " + sdk.format(dropAcceleration, 1) + " m/s^2"
  ], { id: "callout.drop" }));

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "tossedVelocity", value: tossedVelocity },
        { id: "tossedAcceleration", value: tossedAcceleration },
        { id: "dropVelocity", value: dropVelocity },
        { id: "dropAcceleration", value: dropAcceleration }
      ]
    },
    quantities: {
      launchSpeed,
      gravity,
      apexTime,
      apexHeight,
      tossedVelocity,
      tossedAcceleration,
      tossedHeight,
      dropVelocity,
      dropAcceleration,
      dropHeight
    }
  };
}
